+import type {ChatSession} from '../types/session.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+const observeRejection = async (thrownValue: unknown) => {
+  let observedError: Error | undefined;
+  const provider: AIProvider = {
+    // eslint-disable-next-line require-yield -- rejects before yielding chunks to exercise the catch path
+    async *sendMessage() {
+      throw thrownValue;
+    },
+    generateStructured: <T>() => Promise.resolve({} as T),
